1	import java.util.Random;
2	import java.util.List;
3	import java.util.ArrayList;
4	import java.util.Iterator;
5	import java.awt.Color;
6	/**
7	 * A simple predator-prey simulator, based on a rectangular field
8	 * containing rabbits and foxes.
9	 *
10	 * @version 2.0
11	 */
12	public class Simulator
13	{
14	    
15	    /*///////////////////////////////////////////////////////////////
16	                                 CONSTANTS
17	    //////////////////////////////////////////////////////////////*/
18	    
19	    // The default dimensions
20	    private static final int DEFAULT_WIDTH = 120;
21	    private static final int DEFAULT_DEPTH = 80;
22	    
23	    /*///////////////////////////////////////////////////////////////
24	                                   STATE
25	    //////////////////////////////////////////////////////////////*/
26	    
27	    // List of animals in the field.
28	    private List<Actor> animals;
29	    private List<Actor> plants;
30	    // The current state of the field.
31	    private Field field;
32	    
33	    private SimulatorClock clock;
34	    private WeatherHandler weatherHandler;
35	    // The current step of the simulation.
36	    private int step;
37	    // A graphical view of the simulation.
38	    private SimulatorView view;
39	    // creates animal factories
40	    private AnimalFactoryProducer producer;
41	    // handles the simulation of the disease
42	    private DiseaseHandler diseaseHandler;
43	    // swing component dashboard
44	    private Dashboard dashboard;
45	    // generator for the initial terrain and population
46	    private PopulationGenerator populationGenerator;
47	    
48	    /*///////////////////////////////////////////////////////////////
49	                                CONSTRUCTORS
50	    //////////////////////////////////////////////////////////////*/
51	    
52	    /**
53	     * Construct a simulation field with default size.
54	     */
55	    public Simulator() throws Exception
56	    {
57	        this(DEFAULT_DEPTH, DEFAULT_WIDTH);
58	    }
59	    
60	    /**
61	     * Create a simulation field with the given size.
62	     * 
63	     * @param depth Depth of the field. Must be greater than zero.
64	     * @param width Width of the field. Must be greater than zero.
65	     */
66	    public Simulator(int depth, int width) throws Exception
67	    {
68	        if(depth % 20 != 0 || width % 20 != 0) {
69	            throw new Exception("Depth and Width must be factors of 20");
70	        }
71	        
72	        if(width <= 0 || depth <= 0) {
73	            depth = DEFAULT_DEPTH;
74	            width = DEFAULT_WIDTH;
75	        }
76	        
77	        animals = new ArrayList<>();
78	        plants = new ArrayList<>();
79	        field = new Field(depth, width);
80	        clock = new SimulatorClock();
81	        weatherHandler = new WeatherHandler(clock);
82	        diseaseHandler = new DiseaseHandler( field);
83	        producer = new AnimalFactoryProducer(field);
84	        // Create a view of the state of each location in the field.
85	        view = new SimulatorView(depth, width, this);
86	        populationGenerator = new PopulationGenerator(view, field);
87	        
88	        reset();
89	    }
90	    
91	    /**
92	     * Sets the dashboard field to later updates the interface at the end of simulation steps.
93	     * 
94	     * @param newDashboard the dashboard to be updated.
95	     */
96	    public void setDashboard(Dashboard newDashboard) {
97	        this.dashboard = newDashboard;
98	    }
99	    
100	    /*///////////////////////////////////////////////////////////////
101	                          ECOSYSTEM SIMULATION LOGIC
102	    //////////////////////////////////////////////////////////////*/
103	    
104	    /**
105	     * Run the simulation from its current state for a reasonably long period,
106	     * (1000 steps).
107	     */
108	    public void runLongSimulation()
109	    {
110	        simulate(1000);
111	    }
112	    
113	    /**
114	     * Run the simulation from its current state for the given number of steps.
115	     * Stop before the given number of steps if it ceases to be viable.
116	     * 
117	     * @param numSteps The number of steps to run for.
118	     */
119	    public void simulate(int numSteps)
120	    {
121	        for(int step = 1; step <= numSteps && view.isViable(field); step++) {
122	            simulateOneStep();
123	            //delay(1000);   // uncomment this to run more slowly
124	        }
125	    }
126	    
127	    /**
128	     * Run the simulation from its current state for a single step.
129	     * Iterate over the whole field updating the state of each
130	     * fox and rabbit.
131	     */
132	    public void simulateOneStep()
133	    {
134	        step++;
135	        clock.incrementStep();
136	        weatherHandler.updateWeather();
137	        diseaseHandler.simulateDiseaseStep();
138	        
139	        List<Actor> newAnimals = new ArrayList<>();
140	        List<Actor> newPlants = new ArrayList<>();
141	        
142	        actorsAct(plants, newPlants);
143	        actorsAct(animals, newAnimals);        
144	        
145	        view.showStatus(step, field, clock, weatherHandler.getWeather());
146	
147	        if(dashboard != null) {
148	            dashboard.updateDashboard();            
149	        }
150	    }
151	        
152	    /**
153	     * Reset the simulation to a starting position.
154	     */
155	    public void reset()
156	    {
157	        step = 0;
158	        animals.clear();
159	        plants.clear();
160	        populationGenerator.populate(animals, plants);
161	        
162	        // Show the starting state in the view.
163	        view.showStatus(step, field, clock, weatherHandler.getWeather());
164	    }
165	    
166	    /**
167	     * Iterates through a set of actors and makes them act, die if they are dead and subsequently adds the newborns.
168	     * 
169	     * @param actors List of all actors in the field.
170	     * @param newActors List of newborns after actors act.
171	     */
172	    private void actorsAct(List<Actor> actors, List<Actor> newActors) {
173	        for(Iterator<Actor> it = actors.iterator(); it.hasNext(); ) {
174	            Actor actor = it.next();
175	            actor.act(newActors, weatherHandler.getWeather(), clock.getDayState());
176	            if(! actor.isAlive()) {
177	                it.remove();
178	            }
179	        }
180	        actors.addAll(newActors);
181	    }
182	    
183	    /**
184	     * Pause for a given time.
185	     * 
186	     * @param millisec The time to pause for, in milliseconds.
187	     */
188	    private void delay(int millisec)
189	    {
190	        try {
191	            Thread.sleep(millisec);
192	        }
193	        catch (InterruptedException ie) {
194	        }
195	    }
196	}
