1	import java.util.List;
2	import java.util.Iterator;
3	import java.util.Random;
4	import java.lang.reflect.*;
5	/**
6	 * A class representing shared characteristics of animals.
7	 *
8	 * @version 1.3
9	 */
10	public abstract class Animal implements Actor
11	{
12	    
13	    /*///////////////////////////////////////////////////////////////
14	                                  STATE
15	    //////////////////////////////////////////////////////////////*/
16	    
17	    private boolean alive;
18	    private Field field;
19	    private Location location;
20	    protected int age;
21	    protected final Gender gender;
22	    protected int foodLevel;
23	    protected Integer infectionTimestamp;
24	    
25	    private static final Random rand = Randomizer.getRandom();
26	    private static final Class[] ANIMAL_CONSTRUCTOR_SIGNATURE = new Class[] {boolean.class, Field.class, Location.class, Gender.class};
27	    
28	    /*///////////////////////////////////////////////////////////////
29	                                CONSTRUCTOR
30	    //////////////////////////////////////////////////////////////*/
31	    
32	    /**
33	     * Create a new animal at location in field.
34	     * 
35	     * @param randomAge flag indicating whether to randomly generate age and foodLevel or not
36	     * @param field The field currently occupied.
37	     * @param location The location within the field.
38	     * @param gender Gender of the animal
39	     * @param baseLevel base food level of an animal
40	     * @param maxAge maximum age the animal can take
41	     */
42	    public Animal(boolean randomAge, Field field, Location location, Gender gender,int baseLevel, int maxAge)
43	    {
44	        if (randomAge) {
45	            this.age = rand.nextInt(maxAge);
46	            this.foodLevel = rand.nextInt(baseLevel);
47	        } else {
48	            this.foodLevel = baseLevel;
49	            this.age = 0;
50	        }
51	        this.alive = true;
52	        this.field = field;
53	        this.gender = gender;
54	        this.infectionTimestamp = null;
55	        setLocation(location);
56	    }
57	    
58	    /*///////////////////////////////////////////////////////////////
59	                            ANIMAL BEHAVIOUR LOGIC
60	    //////////////////////////////////////////////////////////////*/
61	    
62	    /**
63	     * Increments the age of the animal.
64	     * 
65	     * @param maxAge The maximum age of the animal before he dies.
66	     */
67	    protected void incrementAge(int maxAge)
68	    {
69	        age++;
70	        if(age > maxAge) { 
71	            setDead();
72	        }
73	    }
74	    
75	    /**
76	     * Increment the hunger of the animal.
77	     */
78	    protected void incrementHunger()
79	    {
80	        foodLevel--;
81	        if(foodLevel <= 0) {
82	            setDead();  
83	        }
84	    }
85	    
86	    /**
87	     * Make this animal act - that is: make it do
88	     * whatever it wants/needs to do.
89	     * 
90	     * @param newAnimals A list to receive newly born animals.
91	     * @param weather The current weather
92	     * @param dayState The different state of the day
93	     */
94	    abstract public void act(List<Actor> newAnimals, Weather weather, DayState dayState);
95	    
96	    /**
97	     * Returns the amount by which the hungerlevel would increment by if the animal were to be eaten.
98	     * 
99	     * @return the feeding value
100	     */
101	    abstract public int getFeedingValue();
102	    
103	    /**
104	     * Imitates the meeting of the animal by breeding new born animals.
105	     * 
106	     * @param newAnimals list of the animals to be born.
107	     * @param maxLitter the maximum amount animals that the animal can breed.
108	     * @param breedingProbability the likelyhood of giving birth.
109	     * @param breedingAge the minimum age to be able to breed.
110	     */
111	    protected void meet(List<Actor> newAnimals,int maxLitter, double breedingProbability, int breedingAge)
112	    {
113	        List<Location> adjacent = field.adjacentLocations(getLocation());
114	        Iterator<Location> it = adjacent.iterator();
115	        while(it.hasNext()) {
116	            Location where = it.next();
117	            Object obj = field.getObjectAt(where);
118	            if(obj == null || !this.getClass().equals(obj.getClass())) {
119	                continue;
120	            }
121	            Animal animal = (Animal) obj;
122	            if(animal.getGender() == this.getGender()) {
123	                continue;
124	            }
125	            try
126	            {
127	                Constructor cons = this.getClass().getConstructor(ANIMAL_CONSTRUCTOR_SIGNATURE);
128	                int births = breed(maxLitter, breedingProbability, breedingAge);
129	                giveBirth(newAnimals, births, cons);
130	            }
131	            catch (NoSuchMethodException nsme)
132	            {
133	                nsme.printStackTrace();
134	            }
135	        }
136	    }
137	    
138	    /**
139	     * Returns the amount of animals to breed.
140	     * 
141	     * @param maxLitter the maximum amount of animals that the animal can breed.
142	     * @param breedingProbability indicates the likelyhood of breeding.
143	     * @param breedingAge The minimum age to be able to breed.
144	     * @return an integer representing the amount of animals to give birth.
145	     */
146	    private int breed(int maxLitter, double breedingProbability, int breedingAge)
147	    {
148	        int births = 0;
149	        if(age >= breedingAge){
150	            double randomValue = rand.nextDouble();
151	            if(randomValue <= breedingProbability) {
152	                births = rand.nextInt(maxLitter) + 1;
153	            }
154	        }
155	        return births;
156	    }
157	    
158	    /**
159	     * Gives birth to animal by appending the animals to the input list.
160	     * 
161	     * @param newAnimals list of the new born animals.
162	     * @param births number of animals to give birth.
163	     * @param consutructor of the animals to give birth.
164	     */
165	    private void giveBirth(List<Actor> newAnimals, int births, Constructor cons)
166	    {
167	        List<Location> free = field.getFreeAdjacentLocations(getLocation());
168	        for (int i = 0; i < births && free.size() > 0; i++) {
169	            Location loc = free.remove(0);
170	            Gender randomGender = Utils.getRandomEnumValue(Gender.class);
171	            try {
172	                Object newObj = cons.newInstance(false, field, loc, randomGender);
173	                Animal newBorn = (Animal) newObj;
174	                newAnimals.add(newBorn);        
175	            } catch (InstantiationException e) {
176	                e.printStackTrace();
177	            } catch (IllegalAccessException e) {
178	                e.printStackTrace();
179	            } catch (IllegalArgumentException e) {
180	                e.printStackTrace();
181	            } catch (InvocationTargetException e) {
182	                e.printStackTrace();
183	            }
184	        }
185	    }
186	    
187	    /*///////////////////////////////////////////////////////////////
188	                          ACCESSOR AND MUTATORS
189	    //////////////////////////////////////////////////////////////*/
190	    
191	    /**
192	     * Accessor method for the gender of the animal.
193	     * 
194	     * @return the gender of the animal.
195	     */
196	    protected Gender getGender()
197	    {
198	        return this.gender;
199	    }
200	    
201	    /**
202	     * Accessor method for the timestamp of the infection.
203	     * 
204	     * @return the step at which the animal got infected.
205	     */
206	    public Integer getInfectionTimestamp()
207	    {
208	        return infectionTimestamp;
209	    }
210	    
211	    /**
212	     * Mutator method for the timestamp of the infection.
213	     * 
214	     * @param step The step at which the animal got infected.
215	     */
216	    public void setInfectionTimestamp(int step)
217	    {
218	        infectionTimestamp = step;
219	    }
220	    
221	    /**
222	     * Check whether the animal is alive or not.
223	     * 
224	     * @return true if the animal is still alive.
225	     */
226	    public boolean isAlive()
227	    {
228	        return alive;
229	    }
230	
231	    /**
232	     * Indicate that the animal is no longer alive.
233	     * 
234	     * It is removed from the field.
235	     */
236	    protected void setDead()
237	    {
238	        alive = false;
239	        if(location != null) {
240	            field.clear(location);
241	            location = null;
242	            field = null;
243	        }
244	    }
245	    
246	    /**
247	     * Return the animal's location.
248	     * 
249	     * @return The animal's location.
250	     */
251	    protected Location getLocation()
252	    {
253	        return location;
254	    }
255	    
256	    /**
257	     * Place the animal at the new location in the given field.
258	     * 
259	     * @param newLocation The animal's new location.
260	     */
261	    protected void setLocation(Location newLocation)
262	    {
263	        if(location != null) {
264	            field.clear(location);
265	        }
266	        location = newLocation;
267	        field.place(this, newLocation);
268	    }
269	    
270	    /**
271	     * Return the animal's field.
272	     * 
273	     * @return The animal's field.
274	     */
275	    protected Field getField()
276	    {
277	        return field;
278	    }
279	}
