1	import java.util.List;
2	import java.util.HashMap;
3	/**
4	 * A minimalist implementation of a Fox, a fox can only eat other animals and not plants,
5	 * only the act method is unique to the bear.
6	 *
7	 * @version 1.0
8	 */
9	public class CarnivoreFox extends CarnivoreAnimal
10	{
11	    
12	    /*///////////////////////////////////////////////////////////////
13	                                 CONSTANTS
14	    //////////////////////////////////////////////////////////////*/
15	    
16	    public static int FOUND_FOOD = 0;
17	    private static final int BREEDING_AGE = 12;
18	    private static final int MAX_AGE = 71;
19	    private static final double BREEDING_PROBABILITY = 0.076;
20	    private static final int BASE_HUNGER_LEVEL = 25;
21	    private static final int FEEDING_VALUE = 18;
22	    private static final List<Class<? extends Animal>> PREY_DIET = List.of(Sheep.class, Reindeer.class);
23	    private static final int MAX_LITTER_SIZE = 3;
24	
25	    /*///////////////////////////////////////////////////////////////
26	                                CONSTRUCTOR
27	    //////////////////////////////////////////////////////////////*/
28	    
29	    /**
30	     * Creates a new Fox.
31	     * 
32	     * @param randomAge Boolean flag dictating whether or not the attributes will be assigned a random value
33	     * @param field The environment the animal can move in
34	     * @param location Location of the animal in the field/grid
35	     * @param gender Gender of the animal
36	     */
37	    public CarnivoreFox(boolean randomAge, Field field, Location location, Gender gender)
38	    {
39	        super(
40	                randomAge,
41	                field,
42	                location,
43	                gender,
44	                BASE_HUNGER_LEVEL,
45	                MAX_AGE
46	                );
47	    }
48	    
49	    /*///////////////////////////////////////////////////////////////
50	                            ANIMAL BEHAVIOUR LOGIC
51	    //////////////////////////////////////////////////////////////*/
52	    
53	    /**
54	     * Method in charge of the fox's action's during a step. During a step
55	     * a fox will age, increase in hunger, seek to mate as well as look for food.
56	     * 
57	     * @param newFoxes the new sheeps to be born in case the sheep succesfully mates.
58	     */
59	    public void act(List<Actor> newFoxes, Weather weather, DayState dayState)
60	    {
61	        // Fox will not act at night.
62	        if(dayState == DayState.NIGHT) {
63	            return;
64	        }
65	        incrementAge(MAX_AGE);
66	        incrementHunger();
67	        if(isAlive()) {
68	            meet(newFoxes, MAX_LITTER_SIZE, BREEDING_PROBABILITY, BREEDING_AGE);          
69	            Location newLocation = findFood(PREY_DIET);
70	            if(newLocation != null) {
71	                FOUND_FOOD++;
72	            }
73	            if(newLocation == null) { 
74	                // No food found - try to move to a free location.
75	                newLocation = getField().freeAdjacentLocation(getLocation());
76	            }
77	            // See if it was possible to move.
78	            if(newLocation != null) {
79	                setLocation(newLocation);
80	            }
81	            else {
82	                // Overcrowding.
83	                setDead();
84	            }
85	        }
86	    }
87	    
88	    /**
89	     * Returns the amount by which the hungerlevel would increment by if the animal were to be eaten
90	     * @return the feeding value
91	     */
92	    public int getFeedingValue()
93	    {
94	        return FEEDING_VALUE;
95	    }
96	}

1	import java.util.ArrayList;
2	import java.util.Arrays;
3	import java.util.Iterator;
4	import java.util.List;
5	import java.util.Random;
6	import java.util.HashMap;
7	/**
8	 * An extension of the Animal Class that can only eat a specified type of animals
9	 *
10	 * @version 1.0
11	 */
12	public abstract class CarnivoreAnimal extends Animal
13	{
14	    
15	    /*///////////////////////////////////////////////////////////////
16	                                CONSTRUCTOR
17	    //////////////////////////////////////////////////////////////*/
18	    
19	    /**
20	     * Creates a Carnivore Animal.
21	     * 
22	     * @param randomAge Boolean flag dictating whether or not the attributes will be assigned a random value
23	     * @param field The environment the animal can move in
24	     * @param location Location of the animal in the field/grid
25	     * @param gender Gender of the animal
26	     * @param baseLevel the base hunger index associated with the animal
27	     * @param maxAge the maximum age an animal can take before he dies.
28	     */
29	    
30	    public CarnivoreAnimal(boolean randomAge,
31	                            Field field,
32	                            Location location,
33	                            Gender gender,
34	                            int baseLevel,
35	                            int maxLevel
36	                            )
37	    {
38	        super(randomAge,field, location, gender, baseLevel, maxLevel);
39	    }
40	    
41	    /**
42	     * Seek for the food in adjacent locations that are of type of plant.
43	     * 
44	     * @param preys The preys of the animal.
45	     * @return the location traveled to in order to access the food.
46	     */
47	    public Location findFood(List<Class<? extends Animal>> preys)
48	    {   
49	        Field field = getField();
50	        List<Location> adjacent = field.adjacentLocations(getLocation());
51	        Iterator<Location> it = adjacent.iterator();
52	        while(it.hasNext()) {
53	            Location where = it.next();
54	            Object obj = field.getObjectAt(where);
55	            if(obj instanceof Animal) {
56	                Animal animal = (Animal) obj;
57	                if(preys.contains(animal.getClass())) {
58	                    if(animal.isAlive()) {
59	                        animal.setDead();
60	                        
61	                        this.foodLevel = animal.getFeedingValue();
62	                        return where;
63	                    }
64	                }
65	            }
66	        }
67	        return null; 
68	    }
69	}
