1	import java.util.List;
2	/**
3	 * A minimalist implementation of a Reindeer, a reindeer can only eat plants and not animals,
4	 * only the act method is unique to the reindeer.
5	 *
6	 * @version 1.0
7	 */
8	public class Reindeer extends HerbivoreAnimal
9	{
10	    
11	    /*///////////////////////////////////////////////////////////////
12	                                 CONSTANTS
13	    //////////////////////////////////////////////////////////////*/
14	    
15	    private static final int BREEDING_AGE = 4;
16	    private static final int MAX_AGE = 28;
17	    private static final double BREEDING_PROBABILITY = 0.7;
18	    private static final int MAX_LITTER_SIZE = 5;
19	    private static final int BASE_HUNGER_LEVEL = 15;
20	    private static final int FEEDING_VALUE = 18;
21	    private static final List<Class<? extends Plant>> TARGET_PLANTS = List.of(Grass.class, Sage.class, Sedge.class);
22	    
23	    /*///////////////////////////////////////////////////////////////
24	                                CONSTRUCTOR
25	    //////////////////////////////////////////////////////////////*/
26	    
27	    /**
28	     * Creates a new Reindeer.
29	     * 
30	     * @param randomAge Boolean flag dictating whether or not the attributes will be assigned a random value
31	     * @param field The environment the animal can move in
32	     * @param location Location of the animal in the field/grid
33	     * @param gender Gender of the animal
34	     */
35	    public Reindeer(boolean randomAge, Field field, Location location, Gender gender)
36	    {
37	        super(randomAge, field, location, gender, BASE_HUNGER_LEVEL, MAX_AGE);
38	    }
39	    
40	    /*///////////////////////////////////////////////////////////////
41	                            ANIMAL BEHAVIOUR LOGIC
42	    //////////////////////////////////////////////////////////////*/   
43	    
44	    /**
45	     * Method in charge of the reindeer's action's during a step. During a step,
46	     * a reindeer will age, increase in hunger, seek to mate as well as look for food.
47	     * 
48	     * @param newReindeers the new reeindeers to be born in case the reindeer succesfully mates
49	     */
50	    public void act(List<Actor> newReindeers, Weather weather, DayState dayState) 
51	    {
52	        incrementAge(MAX_AGE);
53	        incrementHunger();
54	        if(!isAlive()) {
55	            return;
56	        }
57	        meet(newReindeers, MAX_LITTER_SIZE, BREEDING_PROBABILITY, BREEDING_AGE);
58	        Location newLocation = findFood(TARGET_PLANTS);
59	        if(newLocation == null) { 
60	            // No food found - try to move to a free location.
61	            newLocation = getField().freeAdjacentLocation(getLocation());
62	        }
63	        // See if it was possible to move.
64	        if(newLocation != null) {
65	            setLocation(newLocation);
66	        }
67	        else {
68	            // Overcrowding.
69	            setDead();
70	        }   
71	    }
72	    
73	    /**
74	     * Returns the amount by which the hungerlevel would increment by if the animal were to be eaten
75	     * @return the feeding value
76	     */
77	    public int getFeedingValue()
78	    {
79	        return FEEDING_VALUE;
80	    }
81	}
