1	import java.util.ArrayList;
2	import java.util.Arrays;
3	import java.util.List;
4	import java.util.Iterator;
5	/**
6	 * An extension of the Animal Class that can only eat a specified type of plants
7	 *
8	 * @version 1.0
9	 */
10	public abstract class HerbivoreAnimal extends Animal
11	{
12	    
13	    /*///////////////////////////////////////////////////////////////
14	                                CONSTRUCTOR
15	    //////////////////////////////////////////////////////////////*/
16	
17	    /**
18	     * Creates a Herbivore Animal.
19	     * 
20	     * @param randomAge Boolean flag dictating whether or not the attributes will be assigned a random value
21	     * @param field The environment the animal can move in
22	     * @param location Location of the animal in the field/grid
23	     * @param gender Gender of the animal
24	     * @param baseLevel the base hunger index associated with the animal
25	     * @param maxAge the maximum age an animal can take before he dies.
26	     */
27	    
28	    public HerbivoreAnimal(boolean randomAge,Field field, Location location, Gender gender, int baseLevel, int maxAge)
29	    {
30	        super(randomAge, field, location, gender, baseLevel, maxAge);
31	    }
32	    
33	    /**
34	     * Seek for the food in adjacent locations that are of type of plant
35	     * @param targetPlants the preferred diet of the animal (e.g eats only grass)
36	     * @return the location traveled to in order to access the food
37	     */
38	    public Location findFood(List<Class<? extends Plant>> targetPlants) 
39	    {
40	        Field field = getField();
41	        List<Location> adjacent = field.adjacentLocations(getLocation());
42	        Iterator<Location> it = adjacent.iterator();
43	        while(it.hasNext()) {
44	            Location where = it.next();
45	            Plant plant = field.getPlantAt(where);
46	            if(plant != null && targetPlants.contains(plant.getClass())) {
47	                if(plant.isAlive()) {
48	                    this.foodLevel += plant.getFeedingValue();
49	                    plant.setDead();
50	                    return where;
51	                }
52	            }
53	        }
54	        return null;
55	    }
56	}
