1	import java.util.Random;
2	import java.util.List;
3	import java.lang.reflect.*;
4	/**
5	 * A blueprint for how a typical plant behaves. A plant grows according to the weather 
6	 * conditions and daylight, and feeds more as it grows.
7	 *
8	 * @version 1.0
9	 */
10	public abstract class Plant implements Actor
11	{
12	    
13	    /*///////////////////////////////////////////////////////////////
14	                                  STATE
15	    //////////////////////////////////////////////////////////////*/
16	    
17	    private static final int FEEDING_FACTOR = 2;
18	    protected boolean alive;
19	    protected Location location;
20	    protected int age;
21	    protected int health;
22	    protected int feedingValue; 
23	    protected Field field;
24	     
25	    private static final Random rand = Randomizer.getRandom();
26	    
27	    /*///////////////////////////////////////////////////////////////
28	                                CONSTRUCTOR
29	    //////////////////////////////////////////////////////////////*/
30	    
31	    /**
32	     * Creates a plant.
33	     * 
34	     * @param randomAge Boolean flag denoting whether or not to randomly generate an age for this plant
35	     * @param field The field currently occupied
36	     * @param location The location of the plant
37	     * @param maxAge The maximum age the plant can take
38	     */
39	    public Plant(boolean randomAge,Field field, Location location, int maxAge) 
40	    {
41	        if(randomAge) {
42	            this.age = rand.nextInt(maxAge);
43	            this.feedingValue = age * FEEDING_FACTOR;
44	        } else {
45	            this.age = 0;
46	            this.feedingValue = 0;
47	        }
48	        this.alive = true;
49	        this.field = field;
50	        setLocation(location);
51	    }
52	    
53	    /*///////////////////////////////////////////////////////////////
54	                            PLANT BEHAVIOUR LOGIC
55	    //////////////////////////////////////////////////////////////*/
56	    
57	    /**
58	     * Make this plant act - that is: make it do
59	     * whatever it wants/needs to do.
60	     * 
61	     * @param newPlants A list to receive newly generated plants.
62	     * @param weather The current weather
63	     * @param dayState The different state of the day
64	     */
65	    
66	    public abstract void act(List<Actor> newPlants, Weather weather, DayState dayState);
67	    
68	    /**
69	     * Increments the age of the plant.
70	     * 
71	     * @param maxAge The maximum age a plant can take.
72	     */
73	    private void incrementAge(int maxAge) {
74	        age++;
75	        if(age > maxAge) {
76	            setDead();
77	        }
78	    }
79	    
80	    /**
81	     * Updates how much the plant will feed if it is to be eaten.
82	     */
83	    private void updateFeedingValue()
84	    {
85	        this.feedingValue = age * FEEDING_FACTOR;
86	    }
87	    
88	    /**
89	     * Updates the age and how much the plant will feed.
90	     * 
91	     * @param maxAge The maximum age a plant can take.
92	     */
93	    protected void grow(int maxAge)
94	    {
95	        incrementAge(maxAge);
96	        updateFeedingValue();
97	    }
98	    
99	    /**
100	     * Imitates the spread/growth of a plant.
101	     * 
102	     * @param spreadProbability likelihood a spreading to the next cell.
103	     * @param newPlants the newly generated plants.
104	     */
105	    protected void multiply(double spreadProbability, List<Actor> newPlants)
106	    {
107	        List<Location> freeLocs = field.getFreeAdjacentTerrain(location);
108	        for ( Location loc : freeLocs) {
109	            if(rand.nextDouble() < spreadProbability) {
110	                try {
111	                    Constructor cons = getConstructor();
112	                    Plant plant = (Plant)cons.newInstance(false, field, loc);
113	                    newPlants.add(plant);
114	                } catch (InstantiationException e) {
115	                    e.printStackTrace();
116	                } catch (IllegalAccessException e) {
117	                    e.printStackTrace();
118	                } catch (IllegalArgumentException e) {
119	                    e.printStackTrace();
120	                } catch (InvocationTargetException e) {
121	                    e.printStackTrace();
122	                }
123	            }
124	        }
125	    }
126	    
127	    /*///////////////////////////////////////////////////////////////
128	                          ACCESSOR AND MUTATORS
129	    //////////////////////////////////////////////////////////////*/
130	    
131	    /**
132	     * Accesor method for the constructor of the plant.
133	     * 
134	     * @return the constructor of the plant.
135	     */
136	    protected Constructor getConstructor() {
137	        try {
138	                Class[] cls = new Class[] {boolean.class, Field.class, Location.class};
139	                Constructor cons = this.getClass().getConstructor(cls);
140	                return cons;
141	        }
142	        catch (NoSuchMethodException nsme) {
143	                nsme.printStackTrace();
144	        }
145	        return null;
146	    }
147	    
148	    /**
149	     * Accessor method to denote whether or not the plant is alive.
150	     * 
151	     * @return flag conveying if the plant is alive.
152	     */
153	    public boolean isAlive()
154	    {
155	        return alive;
156	    }
157	    
158	    /**
159	     * Accessor method for the feeding value of the plant.
160	     * 
161	     * @return the feeding value of the plant.
162	     */
163	    public int getFeedingValue()
164	    {
165	        return feedingValue;
166	    }
167	    
168	    /**
169	     * Mutator method for the location of the plant.
170	     * 
171	     * @param newLocation the new location to be set.
172	     */
173	    protected void setLocation(Location newLocation)
174	    {
175	        if(location != null) {
176	            field.clear(location);
177	        }
178	        location = newLocation;
179	        field.placePlant(this, newLocation);
180	    }
181	    
182	    /**
183	     * Sets the plant dead and removes all references to it, as well as its storage.
184	     */
185	    protected void setDead()
186	    {
187	        alive = false;
188	        if(location != null) {
189	            //errain.clear(location);
190	            field.clearPlant(location);
191	            location = null;
192	            field = null;
193	        }
194	    }
195	}
