1	import java.util.List;
2	/**
3	 * Implementation of a grass plant, the lifecycle of grass consists of spreading, growing and getting eaten
4	 *
5	 * @version 1.0
6	 */
7	public class Grass extends Plant
8	{
9	    
10	    /*///////////////////////////////////////////////////////////////
11	                                 CONSTANTS
12	    //////////////////////////////////////////////////////////////*/
13	    
14	    public static final int MAX_AGE = 25;
15	    public static final double MULTIPLY_PROBABILITY = 0.2;
16	    private static final double OPTIMAL_BREEDING_FACTOR = 4.0;
17	    
18	    /*///////////////////////////////////////////////////////////////
19	                                CONSTRUCTOR
20	    //////////////////////////////////////////////////////////////*/
21	    
22	    /**
23	     * Creates grass.
24	     * 
25	     * @param randomAge Boolean flag to denote whether to assign a random age or not
26	     * @param field field where the plant is emplaced
27	     * @param location Location of the plant within the terrain
28	     */
29	    public Grass(boolean randomAge, Field field, Location location)
30	    {
31	        super(randomAge, field, location,MAX_AGE);
32	    }
33	    
34	    /*///////////////////////////////////////////////////////////////
35	                            PLANT BEHAVIOUR LOGIC
36	    //////////////////////////////////////////////////////////////*/
37	    
38	    /**
39	     * Imitates the actions grass takes, grass grows and multiplies if the weather and daylight conditions are optimal.
40	     * 
41	     * @param weather Handler to get current weather
42	     * @param clock Time handler to get the current day state
43	     * @param newPlants the new plants to be generated
44	     */
45	    @Override
46	    public void act(List<Actor> newPlants, Weather weather, DayState dayState) {
47	        if(dayState == DayState.NIGHT) {
48	            return;
49	        }
50	        grow(MAX_AGE);
51	        if(!isAlive()) {
52	            return;
53	        }
54	        // Change behaviour of grass depending on the weather.
55	        if (weather == Weather.RAIN || weather == Weather.SUNNY) {
56	            multiply((double)OPTIMAL_BREEDING_FACTOR * MULTIPLY_PROBABILITY, newPlants);
57	            return;
58	        }
59	        multiply(MULTIPLY_PROBABILITY, newPlants);
60	    }
61	}
