13	public class Field
14	{
15	    
16	    /*///////////////////////////////////////////////////////////////
17	                                   STATE
18	    //////////////////////////////////////////////////////////////*/
19	    
20	    // A random number generator for providing random locations.
21	    private static final Random rand = Randomizer.getRandom();
22	    // the dimensions for the grids
23	    private final int depth, width;
24	
25	    /*///////////////////////////////////////////////////////////////
26	                               ACTOR STORAGE
27	    //////////////////////////////////////////////////////////////*/
28	    
29	    private Object[][] field;
30	    private Plant [][] terrain;
31	    
32	    /*///////////////////////////////////////////////////////////////
33	                                CONSTRUCTOR
34	    //////////////////////////////////////////////////////////////*/
35	    
36	    /**
37	     * Represent a field of the given dimensions.
38	     * @param depth The depth of the field.
39	     * @param width The width of the field.
40	     */
41	    public Field(int depth, int width)
42	    {
43	        this.depth = depth;
44	        this.width = width;
45	        field = new Object[depth][width];
46	        terrain = new Plant[depth][width];
47	    }
48	    
49	    /*///////////////////////////////////////////////////////////////
50	                            ANIMAL FIELD LOGIC
51	    //////////////////////////////////////////////////////////////*/
52	    
53	    /**
54	     * Empty the field.
55	     */
56	    public void clear()
57	    {
58	        for(int row = 0; row < depth; row++) {
59	            for(int col = 0; col < width; col++) {
60	                field[row][col] = null;
61	                terrain[row][col] = null;
62	            }
63	        }
64	    }
65	    
66	    /**
67	     * Clear the given location.
68	     * 
69	     * @param location The location to clear.
70	     */
71	    public void clear(Location location)
72	    {
73	        field[location.getRow()][location.getCol()] = null;
74	    }
75	    
76	    /**
77	     * Place an animal at the given location.
78	     * If there is already an animal at the location, it will be lost.
79	     * 
80	     * @param animal The animal to be placed.
81	     * @param row Row coordinate of the location.
82	     * @param col Column coordinate of the location.
83	     */
84	    public void place(Object animal, int row, int col)
85	    {
86	        place(animal, new Location(row, col));
87	    }
88	    
89	    /**
90	     * Place an animal at the given location.
91	     * If there is already an animal at the location it will be lost.
92	     * 
93	     * @param animal The animal to be placed.
94	     * @param location Where to place the animal.
95	     */
96	    public void place(Object animal, Location location)
97	    {
98	        field[location.getRow()][location.getCol()] = animal;
99	    }
100	    
101	    /**
102	     * Return the animal at the given location, if any.
103	     * 
104	     * @param location Where in the field.
105	     * @return The animal at the given location, or null if there is none.
106	     */
107	    public Object getObjectAt(Location location)
108	    {
109	        return getObjectAt(location.getRow(), location.getCol());
110	    }
111	    
112	    /**
113	     * Return the animal at the given location, if any.
114	     * 
115	     * @param row The desired row.
116	     * @param col The desired column.
117	     * @return The animal at the given location, or null if there is none.
