135	    /**
136	     * Groups animals that are contained within the same 20 by 20 block within the main animal field.
137	     * 
138	     * @return List of animals contained within the same block.
139	     */
140	    public List<List<Animal>> getAnimalsPerBlock()
141	    {
142	        List<List<Animal>> blocks = new ArrayList<>();
143	        for(int i = 0 ; i < width; i+= 20){
144	            for (int j = 0; j < depth; j+= 20) {
145	                List<Animal> animals = new ArrayList<>();
146	                for (int k = i; k < i + 20; k++) {
