223	    /**
224	     * Get a shuffled list of the free adjacent locations.
225	     * 
226	     * @param location Get locations adjacent to this.
227	     * @return A list of free adjacent locations.
228	     */
229	    public List<Location> getFreeAdjacentTerrain(Location location)
230	    {
231	        return getFreeAdjacent(terrain, location);
232	    }
