234	    /*///////////////////////////////////////////////////////////////
235	                            GRID AGNOSTIC LOGIC
236	    //////////////////////////////////////////////////////////////*/
237	    
238	    /**
239	     * Generate a random location that is adjacent to the
240	     * given location, or is the same location.
241	     * The returned location will be within the valid bounds
242	     * of the field.
243	     * 
244	     * @param location The location from which to generate an adjacency.
245	     * @return A valid location within the grid area.
246	     */
247	    public Location randomAdjacentLocation(Location location)
248	    {
249	        List<Location> adjacent = adjacentLocations(location);
250	        return adjacent.get(0);
251	    }
252	    
253	    /**
254	     * Given a grid and a location, returns the free adjacent location within that grid.
255	     * 
256	     * @param grid A 2 dimensional storage space to store actors.
257	     * @params location the location to seek the adjacents for.
258	     */
259	    private List<Location> getFreeAdjacent(Object[][] grid, Location location) 
260	    {
261	        List<Location> free = new LinkedList<>();
262	        List<Location> adjacent = adjacentLocations(location);
263	        for (Location loc : adjacent) {
264	            if(grid[loc.getRow()][loc.getCol()] == null) {
265	                free.add(loc);
266	            }
267	        }
268	        return free;
269	    }
270	    
271	    /**
272	     * Try to find a free location that is adjacent to the
273	     * given location. If there is none, return null.
274	     * The returned location will be within the valid bounds
275	     * of the field.
276	     * 
277	     * @param location The location from which to generate an adjacency.
278	     * @return A valid location within the grid area.
279	     */
280	    public Location freeAdjacentLocation(Location location)
281	    {
282	        // The available free ones.
283	        List<Location> free = getFreeAdjacentLocations(location);
284	        if(free.size() > 0) {
285	            return free.get(0);
286	        }
287	        else {
288	            return null;
289	        }
290	    }
291	    
292	    /**
293	     * Return a shuffled list of locations adjacent to the given one.
294	     * The list will not include the location itself.
295	     * All locations will lie within the grid.
296	     * 
297	     * @param location The location from which to generate adjacencies.
298	     * @return A list of locations adjacent to that given.
299	     */
300	    public List<Location> adjacentLocations(Location location)
301	    {
302	        assert location != null : "Null location passed to adjacentLocations";
303	        // The list of locations to be returned.
304	        List<Location> locations = new LinkedList<>();
305	        if(location != null) {
306	            int row = location.getRow();
307	            int col = location.getCol();
308	            for(int roffset = -1; roffset <= 1; roffset++) {
309	                int nextRow = row + roffset;
310	                if(nextRow >= 0 && nextRow < depth) {
311	                    for(int coffset = -1; coffset <= 1; coffset++) {
312	                        int nextCol = col + coffset;
313	                        // Exclude invalid locations and the original location.
314	                        if(nextCol >= 0 && nextCol < width && (roffset != 0 || coffset != 0)) {
315	                            locations.add(new Location(nextRow, nextCol));
316	                        }
317	                    }
318	                }
319	            }
320	            // Shuffle the list. Several other methods rely on the list
321	            // being in a random order.
322	            Collections.shuffle(locations, rand);
323	        }
324	        return locations;
325	    }
326	
327	    /**
328	     * Return the depth of the field.
329	     * 
330	     * @return The depth of the field.
331	     */
332	    public int getDepth()
333	    {
334	        return depth;
335	    }
336	    
337	    /**
338	     * Return the width of the field.
339	     * 
340	     * @return The width of the field.
341	     */
342	    public int getWidth()
343	    {
344	        return width;
345	    }
346	}
