1	import java.util.TreeMap;
2	import java.util.List;
3	import java.util.ArrayList;
4	import java.util.Random;
5	/**
6	 * Class responsible for handling the simulation of the disease.
7	 *
8	 * @version 1.0
9	 */
10	public class DiseaseHandler
11	{
12	    
13	    /*///////////////////////////////////////////////////////////////
14	                                 CONSTANTS
15	    //////////////////////////////////////////////////////////////*/
16	    
17	    // cooldown before the animal achieves natural immunity
18	    private static final int DISINFECTION_DURATION = 5;
19	    private final Random rand = Randomizer.getRandom();
20	    private final Field field;
21	    
22	    /*///////////////////////////////////////////////////////////////
23	                                   STATE
24	    //////////////////////////////////////////////////////////////*/
25	    
26	    public static TreeMap<Integer, Integer> count;
27	    private int currentStep;
28	    
29	    /*///////////////////////////////////////////////////////////////
30	                                CONSTRUCTOR
31	    //////////////////////////////////////////////////////////////*/
32	    
33	    /**
34	     * Creates a new disease handler
35	     * @param field The field to later get the animals per block and compute the density
36	     */
37	    public DiseaseHandler(Field field)
38	    {
39	        count = new TreeMap<>();
40	        this.field = field;
41	        currentStep = 0;
42	    }
43	    
44	    /*///////////////////////////////////////////////////////////////
45	                          DISEASE SIMULATION LOGIC
46	    //////////////////////////////////////////////////////////////*/
47	    
48	    /**
49	     * Simulates the disease by iterating through every block in the field, and computing the density of the number of ppl infected 
50	     * in the given block to determine the likelyhood of being infected in the block
51	     */
52	    public void simulateDiseaseStep()
53	    {
54	        // fetch the animal per blocks eg : [block1 : [animal1,animal2, animal3]. block 2: [animal1, animal 2, animal3]...]
55	        List<List<Animal>> blocks = field.getAnimalsPerBlock();
56	        int infectionCount = 0;
57	        currentStep++;
58	        for (List<Animal> block : blocks) {
59	            int densityIndex = 0;
60	            List<Animal> uninfectedAnimals = new ArrayList<>();
61	            for(Animal animal : block) {
62	                if(animal.getInfectionTimestamp() != null && currentStep - animal.getInfectionTimestamp() < DISINFECTION_DURATION) {
63	                    // increase the counter of number of animals infected within this block.
64	                    densityIndex++;
65	                    continue;
66	                }
67	                if(animal.getInfectionTimestamp() == null) {
68	                    uninfectedAnimals.add(animal);
69	                }
70	            }
71	            // compute probability of being infected.
72	            double pValue = (double)((double)densityIndex/(double)block.size());
73	            for(Animal animal : uninfectedAnimals) {
74	                double randNumber = rand.nextDouble();
75	                if(randNumber < pValue ) {
76	                    animal.setInfectionTimestamp(currentStep);
77	                }
78	            }
79	            infectionCount += densityIndex;
80	        }
81	        count.put(currentStep, infectionCount);
82	    }
83	}
