1	/**
2	 * Simulates the behaviour of time by synchronizing itself with the current step of the simulation(linear formula: time = k * step)
3	 *
4	 * @version 1.0
5	 */
6	public class SimulatorClock
7	{
8	    
9	    /*///////////////////////////////////////////////////////////////
10	                                   STATE
11	    //////////////////////////////////////////////////////////////*/
12	    
13	    private final int INITIAL_TIME = 12;
14	    private final int TIME_FACTOR = 3;
15	    private final int STEPS_PER_DAY = 8;
16	    private int step;
17	    private int dayCount;
18	    
19	    /*///////////////////////////////////////////////////////////////
20	                                CONSTRUCTOR
21	    //////////////////////////////////////////////////////////////*/    
22	    
23	    /**
24	     * Constructor for objects of class SimulatorClock.
25	     */
26	    public SimulatorClock()
27	    {
28	        step = 0;
29	    }
30	    
31	    /**
32	     * Returns a string indicating the time of the day in a human friendly format.
33	     * 
34	     * @return A string of the current time of the day in a Day:Hour:Minute format.
35	     */
36	    
37	    public String getStringTime()
38	    {
39	        String hourString = Utils.padLeft(String.valueOf(getHourOfDay()), 2);
40	        String minuteString = Utils.padRight(String.valueOf(getMinuteOfDay()), 2);
41	        return String.format("Day: %s | %s : %s ",getDayCount(),hourString, minuteString);
42	    }
43	    
44	    /*///////////////////////////////////////////////////////////////
45	                          TIME SIMULATION LOGIC
46	    //////////////////////////////////////////////////////////////*/
47	    
48	    /**
49	     * Acessor method for the current time(starts at mid day).
50	     * 
51	     * @return the current time.
52	     */
53	    public double getTime()
54	    {
55	        return (((double)(TIME_FACTOR) * step) + INITIAL_TIME) % 24;
56	    }
57	    
58	    /**
59	     * Accessor method for the current hour of the day.
60	     * 
61	     * @return the current hour (floored).
62	     */
63	    public int getHourOfDay()
64	    {
65	        return (int) getTime();
66	    }
67	    
68	    /**
69	     * The remainder of the current hours.
70	     * 
71	     * @return the minutes passed since the start of the last hour.
72	     */
73	    public int getMinuteOfDay()
74	    {
75	        return (int)((getTime() - (double)getHourOfDay()) * 100.0 * 0.6);
76	    }
77	    
78	    /**
79	     * Increments the internal steps of the clock.
80	     */
81	    public void incrementStep()
82	    {
83	        step++;
84	    }
85	    
86	    /**
87	     * Returns the number of days passed since the start of the simulation(starts at day 1).
88	     * 
89	     * @return the current day of the simulation.
90	     */
91	    public int getDayCount()
92	    {
93	        return ((int)((step + (INITIAL_TIME/TIME_FACTOR)) / STEPS_PER_DAY) + 1);
94	    }
95	    
96	    /**
97	     * Returns the current state of the day.
98	     * 
99	     * @returns the state of the day.
100	     */
101	    public DayState getDayState()
102	    {
103	        if(getTime() > 24 || getTime() < 6) {
104	            return DayState.NIGHT;
105	        } else {
106	            return DayState.DAYLIGHT;
107	        }
108	    }
109	}
