2	/**
3	 * Provide control over the randomization of the simulation. By using the shared, fixed-seed 
4	 * randomizer, repeated runs will perform exactly the same (which helps with testing). Set 
5	 * 'useShared' to false to get different random behaviour every time.
6	 *
7	 * @version 2016.02.29
8	 */
9	public class Randomizer
10	{
11	    // The default seed for control of randomization.
12	    private static final int SEED = 1111;
13	    // A shared Random object, if required.
14	    private static final Random rand = new Random(SEED);
15	    // Determine whether a shared random generator is to be provided.
16	    private static final boolean useShared = true;
17	
18	    /**
19	     * Constructor for objects of class Randomizer
20	     */
21	    public Randomizer()
22	    {
23	    }
24	
25	    /**
26	     * Provide a random generator.
27	     * @return A random object.
28	     */
29	    public static Random getRandom()
30	    {
31	        if(useShared) {
32	            return rand;
33	        }
34	        else {
35	            return new Random();
36	        }
37	    }
38	    
39	    /**
40	     * Reset the randomization.
41	     * This will have no effect if randomization is not through
42	     * a shared Random generator.
43	     */
44	    public static void reset()
45	    {
46	        if(useShared) {
47	            rand.setSeed(SEED);
48	        }
49	    }
50	}
