7	public class Sage extends Plant
8	{
9	    
10	    /*///////////////////////////////////////////////////////////////
11	                                 CONSTANTS
12	    //////////////////////////////////////////////////////////////*/
13	    
14	    public static final int MAX_AGE = 20;
15	    public static final double MULTIPLY_PROBABILITY = 0.15;
16	    private static final double OPTIMAL_BREEDING_FACTOR = 4.0;
17	    
18	    /*///////////////////////////////////////////////////////////////
19	                                CONSTRUCTOR
20	    //////////////////////////////////////////////////////////////*/
21	    
22	    /**
23	     * Creates sage.
24	     * 
25	     * @param randomAge Boolean flag to denote whether to assign a random age or not
26	     * @param field field where the plant is emplaced
27	     * @param location Location of the plant within the terrain
28	     */
29	    public Sage(boolean randomAge, Field field, Location location)
30	    {
31	        super(randomAge, field, location,MAX_AGE);
32	    }
33	
34	    /*///////////////////////////////////////////////////////////////
35	                            PLANT BEHAVIOUR LOGIC
36	    //////////////////////////////////////////////////////////////*/
37	    /**
38	     * Imitates the actions sage takes, sage grows and multiplies if the weather and daylight conditions are optimal.
39	     * 
40	     * @param weather Handler to get current weather
41	     * @param clock Time handler to get the current day state
42	     * @param newPlants the new plants to be generated
43	     */
44	    @Override
45	    public void act(List<Actor> newPlants, Weather weather, DayState dayState) {
46	        if(dayState == DayState.NIGHT) {
47	            return;
48	        }
49	        grow(MAX_AGE);
50	        if(!isAlive()) {
51	            return;
52	        } 
53	        // Change behaviour of sage depending on the weather.
54	        if (weather == Weather.RAIN || weather == Weather.SUNNY) {
55	            multiply((double)OPTIMAL_BREEDING_FACTOR * MULTIPLY_PROBABILITY, newPlants);
56	            return;
57	        }
58	        multiply(MULTIPLY_PROBABILITY, newPlants);
59	    }
60	}
