1	import java.util.Random;
2	import java.util.List;
3	import java.awt.Color;
4	/**
5	 * A class responsible for generating the population,
6	 * as well as setting up the colours associated with each animal and plant class.
7	 *
8	 * @version 1.0
9	 */
10	public class PopulationGenerator
11	{
12	    
13	    /*///////////////////////////////////////////////////////////////
14	                                 CONSTANTS
15	    //////////////////////////////////////////////////////////////*/
16	    
17	    // The probability that an animal will be created in any given grid position.
18	    private static final double FOX_CREATION_PROBABILITY = 0.09;  
19	    private static final double REINDEER_CREATION_PROBABILITY = 0.11;
20	    private static final double SHEEP_CREATION_PROBABILITY = 0.11;
21	    private static final double BEAR_CREATION_PROBABILITY = 0.04;
22	    private static final double WOLVERINE_CREATION_PROBABILITY = 0.09;
23	    // The probability that a plant will be created in any given grid position.
24	    private static final double GRASS_SPAWN_PROBABILITY = 0.09;
25	    private static final double SAGE_SPAWN_PROBABILITY = 0.075;
26	    private static final double SEDGE_SPAWN_PROBABILITY = 0.07;
27	    // A constant for initial number of infections in the generated population.
28	    private static final int INITIAL_INFECTION_COUNT = 11;
29	    
30	    /*///////////////////////////////////////////////////////////////
31	                                   STATE
32	    //////////////////////////////////////////////////////////////*/
33	    
34	    private SimulatorView view;
35	    private AnimalFactoryProducer producer;
36	    private Field field;
37	    
38	    /*///////////////////////////////////////////////////////////////
39	                                CONSTRUCTOR
40	    //////////////////////////////////////////////////////////////*/
41	    
42	    /**
43	     * Construct a population generator and set up the colours for representation of each animal class.
44	     */
45	    public PopulationGenerator(SimulatorView view, Field field)
46	    {
47	        this.view = view;
48	        this.field = field;
49	        producer = new AnimalFactoryProducer(field);
50	        setUpColors();
51	    }
52	    
53	    /**
54	     * The RGB colours associated with the given animals and plants passed to the constructor of Color class from awt library.
55	     */
56	    private void setUpColors()
57	    {
58	        view.setColor(CarnivoreFox.class, new Color(227, 93, 57));
59	        view.setColor(Grass.class, new Color(50, 184, 121));
60	        view.setColor(Sage.class, new Color(27, 117, 19));
61	        view.setColor(Reindeer.class, new Color(217, 162, 147));
62	        view.setColor(Sheep.class, Color.LIGHT_GRAY);
63	        view.setColor(Bear.class, new Color(112, 62, 49));
64	        view.setColor(Wolverine.class, Color.BLACK);
65	        view.setColor(Sedge.class, new Color(78, 117, 19));
66	        view.showColors();
67	    }
68	    
69	    /**
70	     * Populate the grid with animals and plants, infect the animals.
71	     * 
72	     * @param animals The list of Actor objects representing animals in the simulation
73	     * @param plants The list of Plant objects representing plants in the simulation
74	     */
75	    public void populate(List<Actor> animals , List<Actor> plants)
76	    {
77	      // Set up a randomizer, animal and plant factories
78	      Random rand = Randomizer.getRandom();
79	      field.clear();
80	      AnimalFactory herbivoreFactory = producer.getFactory(false);
81	      AnimalFactory carnivoreFactory = producer.getFactory(true);
82	      PlantFactory plantFactory = new PlantFactory(field);
83	      
84	      // Nested loop to go through every location on the grid and generate an animal of a certain class 
85	      // based on a comparison of randomised double with the creation probability of every animal
86	      for(int row = 0; row < field.getDepth(); row++) {
87	          for(int col = 0; col < field.getWidth(); col++) {
88	              Location location = new Location(row, col);
89	              if(rand.nextDouble() <= FOX_CREATION_PROBABILITY) {                  
90	                  animals.add(carnivoreFactory.getAnimal("FOX", location));
91	              }
92	              else if(rand.nextDouble() <= REINDEER_CREATION_PROBABILITY) {
93	                  animals.add(herbivoreFactory.getAnimal("SHEEP", location));
94	              }
95	              else if (rand.nextDouble() <= SHEEP_CREATION_PROBABILITY) {
96	                  animals.add(herbivoreFactory.getAnimal("REINDEER", location));
97	              }
98	              else if (rand.nextDouble() <= BEAR_CREATION_PROBABILITY) {
99	                  animals.add(carnivoreFactory.getAnimal("BEAR", location));
100	              }
101	              else if (rand.nextDouble() <= WOLVERINE_CREATION_PROBABILITY) {
102	                  animals.add(carnivoreFactory.getAnimal("WOLVERINE", location));
103	              }
104	                // else leave the location empty.
105	          }
106	      }
107	        
108	      // A loop to go through the list of generated animals and infect 11 animals
109	      for (int i = 0; i < INITIAL_INFECTION_COUNT; i++) {
110	          if (animals.get(i) instanceof Animal){
111	              Animal animal = (Animal) (animals.get(i));
112	              animal.setInfectionTimestamp(0);
113	          }    
